<template>
  <el-drawer title="原单关联单据" :visible.sync="visible" size="min(1280px,96vw)" append-to-body :wrapper-closable="false">
    <div v-loading="loading" class="relations-body"><div class="identity"><strong>平台主单 {{ tid }}</strong><p>{{ channel ? shop(channel) : '全部店铺，按各记录所属店铺区分' }}</p><p class="hint">按原交易查看本地已保存的平台单据及 SO、TK、HH 关联。尚未匹配原单的申请可在各标签页继续查询。</p></div><el-alert v-if="error" :title="error" type="warning" :closable="false" />
      <section v-for="g in groups" :key="g.kind"><h3>{{ names[g.kind] }} <span class="hint">{{ g.has_more?'最近50条':g.rows.length+' 条' }}</span></h3><el-table :data="g.rows" row-key="record_key" empty-text="本地尚无该类型的关联记录"><el-table-column label="平台单号 / 子单" min-width="230"><template slot-scope="s"><strong>{{ s.row.document_no }}</strong><div class="hint">{{ s.row.platform_oid || '主订单' }}</div><div class="hint">{{ shop(s.row.channel_id) }}</div></template></el-table-column><el-table-column label="平台状态 / 转单" min-width="180"><template slot-scope="s">{{ platformState(g.kind,s.row.platform_status) }}<div class="hint">{{ conversion(g.kind,s.row.conversion_state) }}</div><div class="warning">{{ s.row.source_error || s.row.conversion_error }}</div></template></el-table-column><el-table-column label="关联 OMS 单据" min-width="235"><template slot-scope="s"><router-link v-if="s.row.business_id && canBusiness(g.kind)" :to="businessLink(g.kind,s.row)" @click.native="visible=false">{{ s.row.business_no }}</router-link><span v-else>{{ s.row.business_no || '尚未转单 / 关联' }}</span><div class="hint">{{ businessState(g.kind,s.row.business_state) }}</div></template></el-table-column><el-table-column label="数量 / 金额" width="130"><template slot-scope="s">{{ g.kind==='EXCHANGE'?s.row.quantity+' 件':'¥ '+Number(s.row.amount).toFixed(2) }}</template></el-table-column><el-table-column label="平台修改时间" prop="source_modified" min-width="170" /><el-table-column label="操作" width="100" fixed="right"><template slot-scope="s"><el-button v-if="canQuery(g.kind)" type="text" @click="openRecord(g.kind,s.row)">平台详情</el-button></template></el-table-column></el-table><el-button v-if="g.has_more" type="text" @click="openList(g.kind)">进入{{ names[g.kind] }}查看完整记录</el-button></section>
      <div class="footer"><el-button :loading="loading" @click="open(tid,channel)">刷新关联</el-button><el-button @click="visible=false">关闭</el-button></div>
    </div>
  </el-drawer>
</template>
<script>
import { relatedPlatformDocuments } from '@/api/order/platformDocuments'
import { documentKinds } from './platformDocumentsPresentation'
import { platforms, states } from './exchangeLabels'
import { conversionStates } from './platformExchangeLabels'
import { label as refundLabel } from './refundLabels'
export default { name:'PlatformDocumentRelations',props:{channels:Array},data:()=>({visible:false,loading:false,tid:'',channel:'',groups:[],error:'',sequence:0,names:documentKinds}),methods:{can(p){const values=this.$store.getters.permissions||[];return values.includes('*:*:*')||values.includes(p)},canQuery(k){return this.can(k==='ORDER'?'order:order:query':`order:${k.toLowerCase()}:query`)},canBusiness(k){return k==='REFUND'?this.can('order:refund:list')&&this.canQuery(k):k==='EXCHANGE'?this.can('order:exchange:list')&&this.canQuery(k):this.can('order:order:list')&&this.canQuery(k)},shop(id){const c=this.channels.find(c=>String(c.channel_id)===String(id));return c?c.channel_name:`渠道 ${id}`},platformState(k,s){return k==='EXCHANGE'?platforms[s]||s:k==='REFUND'?refundLabel(s):({WAIT_BUYER_PAY:'待付款',WAIT_SELLER_SEND_GOODS:'已付款待发货',WAIT_BUYER_CONFIRM_GOODS:'已发货',TRADE_FINISHED:'交易完成',TRADE_CLOSED:'交易关闭',TRADE_CLOSED_BY_TAOBAO:'交易关闭'})[s]||s},conversion(k,s){return k==='ORDER'?({PENDING:'待处理',PROCESSING:'处理中',WAITING:'待转单',EXCEPTION:'转单异常',SUCCESS:'已转单'})[s]||s:conversionStates[s]||s},businessState(k,s){if(!s)return'';return k==='EXCHANGE'?states[s]||s:k==='REFUND'?refundLabel(s):({WAIT_ALLOCATION:'待分仓',WAIT_REVIEW:'待审核',WAIT_CARRIER:'待匹配快递',WAIT_DISPATCH:'待下发仓库',DISPATCHING:'下发仓库中',WAREHOUSE_PROCESSING:'仓库处理中',PART_DISPATCHED:'部分下发',PART_ALLOCATED:'部分分仓',SHIPPED:'已发货',PART_SHIPPED:'部分发货',VOIDED:'已作废',CUTTING:'截单处理中',CLOSED:'余量已终止'})[s]||s},async open(tid,channel){const seq=++this.sequence;this.tid=String(tid);this.channel=channel?String(channel):'';this.visible=true;this.loading=true;this.error='';this.groups=[];try{const r=(await relatedPlatformDocuments({platformTid:this.tid,channelId:this.channel})).data;if(seq===this.sequence)this.groups=r.groups}catch(_){if(seq===this.sequence)this.error='关联单据加载失败，请刷新重试'}finally{if(seq===this.sequence)this.loading=false}},openRecord(kind,row){this.visible=false;this.$emit('open',{...row,kind})},openList(kind){this.visible=false;this.$emit('open',{kind,channel_id:this.channel,platform_tid:this.tid})},businessLink(kind,row){return{path:kind==='ORDER'?'/oms-order/business':kind==='REFUND'?'/oms-order/businessRefunds':'/oms-order/exchanges',query:kind==='ORDER'?{view:'business',orderId:row.business_id}:kind==='EXCHANGE'?{exchangeId:row.business_id}:{id:row.business_id}}}} }
</script>
<style scoped>.relations-body{padding:0 24px 24px;overflow:auto;height:calc(100vh - 90px)}.identity{padding:20px;background:#f4f7fc;border-radius:6px;line-height:1.8}.identity strong{font-size:18px}.identity p{margin:6px 0}.hint{font-size:12px;color:#8290a4;line-height:1.8}.warning{font-size:12px;color:#b77515;line-height:1.7;overflow-wrap:anywhere}section{margin:24px 0}h3{font-size:15px}.footer{display:flex;justify-content:flex-end;gap:12px;padding-top:16px}a{color:#1677ff}.el-table strong{overflow-wrap:anywhere}</style>
